const sqlite3 = require('sqlite3').verbose();
const path = require('path');

const db = new sqlite3.Database(path.resolve(__dirname, '../../task_management.db'), (err) => {
  if (err) {
    console.error('Error opening database:', err.message);
  } else {
    console.log('Connected to SQLite database.');
    initializeDatabase();
  }
});

function initializeDatabase() {
  db.serialize(() => {
    // Create users table
    db.run(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);

    // Create tasks table
    db.run(`
      CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        priority TEXT DEFAULT 'medium',
        status TEXT DEFAULT 'todo',
        due_date DATETIME,
        tags TEXT,
        created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
        user_id INTEGER,
        FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
      )
    `);

    // Create index on user_id for faster queries
    db.run(`
      CREATE INDEX IF NOT EXISTS idx_tasks_user_id ON tasks(user_id)
    `);
  });
}

module.exports = db;

const db = require('../config/database');
const bcrypt = require('bcryptjs');

class User {
  static create({ username, email, password }) {
    return new Promise((resolve, reject) => {
      bcrypt.hash(password, 10, (err, hashedPassword) => {
        if (err) reject(err);

        db.run(
          'INSERT INTO users (username, email, password) VALUES (?, ?, ?)',
          [username, email, hashedPassword],
          function (err) {
            if (err) reject(err);
            resolve({ id: this.lastID, username, email });
          }
        );
      });
    });
  }

  static findByEmail(email) {
    return new Promise((resolve, reject) => {
      db.get('SELECT * FROM users WHERE email = ?', [email], (err, row) => {
        if (err) reject(err);
        resolve(row);
      });
    });
  }

  static findById(id) {
    return new Promise((resolve, reject) => {
      db.get('SELECT * FROM users WHERE id = ?', [id], (err, row) => {
        if (err) reject(err);
        resolve(row);
      });
    });
  }
}

module.exports = User;

const db = require('../config/database');

class Task {
  static create({ title, description, priority, status, due_date, tags, user_id }) {
    return new Promise((resolve, reject) => {
      const tagsJson = Array.isArray(tags) ? JSON.stringify(tags) : tags || '[]';
      db.run(
        `INSERT INTO tasks (title, description, priority, status, due_date, tags, user_id) 
         VALUES (?, ?, ?, ?, ?, ?, ?)`,
        [title, description, priority, status, due_date, tagsJson, user_id],
        function (err) {
          if (err) reject(err);
          resolve({ id: this.lastID, title, description, priority, status, due_date, tags, user_id });
        }
      );
    });
  }

  static findById(id) {
    return new Promise((resolve, reject) => {
      db.get('SELECT * FROM tasks WHERE id = ?', [id], (err, row) => {
        if (err) reject(err);
        if (row) {
          row.tags = JSON.parse(row.tags || '[]');
        }
        resolve(row);
      });
    });
  }

  static findByUserId(userId, filters = {}, sortOptions = {}, pagination = {}) {
    return new Promise((resolve, reject) => {
      let query = 'SELECT * FROM tasks WHERE user_id = ?';
      const params = [userId];

      // Filtering
      if (filters.status) {
        query += ' AND status = ?';
        params.push(filters.status);
      }
      if (filters.priority) {
        query += ' AND priority = ?';
        params.push(filters.priority);
      }
      if (filters.tags && filters.tags.length > 0) {
        // Simple tag filtering - matches if task contains any of the provided tags
        // This is a basic implementation; for production, consider a proper many-to-many relationship
        const tagConditions = filters.tags.map(() => 'tags LIKE ?').join(' OR ');
        query += ` AND (${tagConditions})`;
        params.push(...filters.tags.map(tag => `%${tag}%`));
      }

      // Search by title
      if (filters.search) {
        query += ' AND title LIKE ?';
        params.push(`%${filters.search}%`);
      }

      // Sorting
      const sortBy = sortOptions.sortBy || 'created_at';
      const sortOrder = sortOptions.sortOrder === 'asc' ? 'ASC' : 'DESC';
      const validSortColumns = ['title', 'priority', 'status', 'due_date', 'created_at', 'updated_at'];
      if (validSortColumns.includes(sortBy)) {
        query += ` ORDER BY ${sortBy} ${sortOrder}`;
      } else {
        query += ' ORDER BY created_at DESC';
      }

      // Pagination
      const limit = pagination.limit || 10;
      const offset = pagination.offset || 0;
      query += ' LIMIT ? OFFSET ?';
      params.push(limit, offset);

      db.all(query, params, (err, rows) => {
        if (err) reject(err);
        // Parse tags JSON for each task
        const tasks = rows.map(row => ({
          ...row,
          tags: JSON.parse(row.tags || '[]')
        }));
        resolve(tasks);
      });
    });
  }

  static update(id, updates) {
    return new Promise((resolve, reject) => {
      const fields = [];
      const values = [];

      Object.keys(updates).forEach(key => {
        if (key === 'tags' && Array.isArray(updates[key])) {
          fields.push(`${key} = ?`);
          values.push(JSON.stringify(updates[key]));
        } else if (key !== 'id' && key !== 'user_id' && key !== 'created_at') {
          fields.push(`${key} = ?`);
          values.push(updates[key]);
        }
      });

      if (fields.length === 0) {
        resolve(null);
        return;
      }

      fields.push('updated_at = ?');
      values.push(new Date().toISOString());
      values.push(id);

      const query = `UPDATE tasks SET ${fields.join(', ')} WHERE id = ?`;

      db.run(query, values, function (err) {
        if (err) reject(err);
        if (this.changes === 0) {
          resolve(null);
        } else {
          resolve({ id, ...updates });
        }
      });
    });
  }

  static delete(id) {
    return new Promise((resolve, reject) => {
      db.run('DELETE FROM tasks WHERE id = ?', [id], function (err) {
        if (err) reject(err);
        resolve(this.changes > 0);
      });
    });
  }

  static countByUserId(userId, filters = {}) {
    return new Promise((resolve, reject) => {
      let query = 'SELECT COUNT(*) as count FROM tasks WHERE user_id = ?';
      const params = [userId];

      // Apply same filters as findByUserId (excluding pagination and sort)
      if (filters.status) {
        query += ' AND status = ?';
        params.push(filters.status);
      }
      if (filters.priority) {
        query += ' AND priority = ?';
        params.push(filters.priority);
      }
      if (filters.tags && filters.tags.length > 0) {
        const tagConditions = filters.tags.map(() => 'tags LIKE ?').join(' OR ');
        query += ` AND (${tagConditions})`;
        params.push(...filters.tags.map(tag => `%${tag}%`));
      }
      if (filters.search) {
        query += ' AND title LIKE ?';
        params.push(`%${filters.search}%`);
      }

      db.get(query, params, (err, row) => {
        if (err) reject(err);
        resolve(row.count);
      });
    });
  }
}

module.exports = Task;

const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

module.exports = { authenticateToken };

const User = require('../models/User');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

const generateToken = (userId) => {
  return jwt.sign(
    { userId },
    process.env.JWT_SECRET || 'your-secret-key',
    { expiresIn: '15m' }
  );
};

const generateRefreshToken = (userId) => {
  return jwt.sign(
    { userId },
    process.env.JWT_REFRESH_SECRET || 'your-refresh-secret-key',
    { expiresIn: '7d' }
  );
};

exports.register = async (req, res) => {
  try {
    const { username, email, password } = req.body;

    // Check if user already exists
    const existingUser = await User.findByEmail(email);
    if (existingUser) {
      return res.status(400).json({ error: 'User already exists with this email' });
    }

    // Create new user
    const user = await User.create({ username, email, password });

    // Generate tokens
    const accessToken = generateToken(user.id);
    const refreshToken = generateRefreshToken(user.id);

    // Set refresh token as httpOnly cookie
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
    });

    res.status(201).json({
      message: 'User registered successfully',
      user: { id: user.id, username: user.email, email: user.email },
      accessToken
    });
  } catch (error) {
    console.error('Registration error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
};

exports.login = async (req, res) {
  try {
    const { email, password } = req.body;

    // Find user by email
    const user = await User.findByEmail(email);
    if (!user) {
      return res.status(400).json({ error: 'Invalid credentials' });
    }

    // Check password
    const isMatch = await bcrypt.compare(password, user.password);
    if (!isMatch) {
      return res.status(400).json({ error: 'Invalid credentials' });
    }

    // Generate tokens
    const accessToken = generateToken(user.id);
    const refreshToken = generateRefreshToken(user.id);

    // Set refresh token as httpOnly cookie
    res.cookie('refreshToken', refreshToken, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict',
      maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
    });

    res.json({
      message: 'Login successful',
      user: { id: user.id, username: user.username, email: user.email },
      accessToken
    });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
};

exports.refreshToken = (req, res) => {
  const refreshToken = req.cookies.refreshToken;

  if (!refreshToken) {
    return res.status(401).json({ error: 'Refresh token required' });
  }

  jwt.verify(refreshToken, process.env.JWT_REFRESH_SECRET || 'your-refresh-secret-key', (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired refresh token' });
    }

    const newAccessToken = generateToken(user.userId);
    res.json({ accessToken: newAccessToken });
  });
};

exports.logout = (req, res) => {
  res.clearCookie('refreshToken');
  res.json({ message: 'Logged out successfully' });
};

