const Task = require('../models/Task');
const z = require('zod');

// Validation schemas
const taskSchema = z.object({
  title: z.string().min(1, 'Title is required'),
  description: z.string().optional(),
  priority: z.enum(['low', 'medium', 'high']).default('medium'),
  status: z.enum(['todo', 'in_progress', 'done']).default('todo'),
  due_date: z.string().datetime().optional().nullable(),
  tags: z.array(z.string()).default([])
});

const updateTaskSchema = taskSchema.partial();

exports.createTask = async (req, res) => {
  try {
    // Validate input
    const validatedData = taskSchema.parse(req.body);

    // Add user_id from authenticated user
    const taskData = {
      ...validatedData,
      user_id: req.user.userId
    };

    const task = await Task.create(taskData);
    res.status(201).json(task);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({ error: 'Validation failed', details: error.errors });
    }
    console.error('Create task error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
};

exports.getTasks = async (req, res) => {
  try {
    const userId = req.user.userId;

    // Parse query parameters
    const filters = {};
    if (req.query.status) filters.status = req.query.status;
    if (req.query.priority) filters.priority = req.query.priority;
    if (req.query.search) filters.search = req.query.search;
    if (req.query.tags) {
      // Expect comma-separated tags
      filters.tags = req.query.tags.split(',').map(tag => tag.trim());
    }

    const sortOptions = {};
    if (req.query.sortBy) sortOptions.sortBy = req.query.sortBy;
    if (req.query.sortOrder) sortOptions.sortOrder = req.query.sortOrder;

    const pagination = {};
    if (req.query.limit) pagination.limit = parseInt(req.query.limit);
    if (req.query.offset) pagination.offset = parseInt(req.query.offset);

    const tasks = await Task.findByUserId(userId, filters, sortOptions, pagination);
    const totalCount = await Task.countByUserId(userId, filters);

    res.json({
      tasks,
      pagination: {
        limit: pagination.limit || 10,
        offset: pagination.offset || 0,
        total: totalCount
      }
    });
  } catch (error) {
    console.error('Get tasks error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
};

exports.getTaskById = async (req, res) => {
  try {
    const task = await Task.findById(req.params.id);
    if (!task) {
      return res.status(404).json({ error: 'Task not found' });
    }

    // Check if task belongs to current user
    if (task.user_id !== req.user.userId) {
      return res.status(403).json({ error: 'Access denied' });
    }

    res.json(task);
  } catch (error) {
    console.error('Get task by ID error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
};

exports.updateTask = async (req, res) => {
  try {
    const taskId = req.params.id;

    // Check if task exists and belongs to user
    const existingTask = await Task.findById(taskId);
    if (!existingTask) {
      return res.status(404).json({ error: 'Task not found' });
    }

    if (existingTask.user_id !== req.user.userId) {
      return res.status(403).json({ error: 'Access denied' });
    }

    // Validate input
    const validatedData = updateTaskSchema.parse(req.body);

    const updatedTask = await Task.update(taskId, validatedData);
    if (!updatedTask) {
      return res.status(400).json({ error: 'No valid fields to update' });
    }

    res.json(updatedTask);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return res.status(400).json({ error: 'Validation failed', details: error.errors });
    }
    console.error('Update task error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
};

exports.deleteTask = async (req, res) => {
  try {
    const taskId = req.params.id;

    // Check if task exists and belongs to user
    const existingTask = await Task.findById(taskId);
    if (!existingTask) {
      return res.status(404).json({ error: 'Task not found' });
    }

    if (existingTask.user_id !== req.user.userId) {
      return res.status(403).json({ error: 'Access denied' });
    }

    const deleted = await Task.delete(taskId);
    if (!deleted) {
      return res.status(400).json({ error: 'Failed to delete task' });
    }

    res.json({ message: 'Task deleted successfully' });
  } catch (error) {
    console.error('Delete task error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
};

