      const response = await request(app)
        .get('/api/tasks?status=done')
        .set('Authorization', `Bearer ${accessToken}`);

      expect(response.status).toBe(200);
      expect(response.body.tasks.length).toBe(1);
      expect(response.body.tasks[0].status).toBe('done');
    });

    it('should filter tasks by priority', async () => {
      // Create a high priority task
      const timestamp = Date.now();
      await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'High Priority Task ' + timestamp,
          description: 'High priority task',
          priority: 'high',
          status: 'todo'
        });

      const response = await request(app)
        .get('/api/tasks?priority=high')
        .set('Authorization', `Bearer ${accessToken}`);

      expect(response.status).toBe(200);
      expect(response.body.tasks.length).toBe(1);
      expect(response.body.tasks[0].priority).toBe('high');
    });
  });

  describe('GET /api/tasks/:id', () => {
    it('should get a specific task by ID', async () => {
      // Create a task
      const timestamp = Date.now();
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Specific Task ' + timestamp,
          description: 'Task details',
          priority: 'high',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Get the task
      const response = await request(app)
        .get(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`);

      expect(response.status).toBe(200);
      expect(response.body.title).toBe('Specific Task ' + timestamp);
      expect(response.body.description).toBe('Task details');
      expect(response.body.priority).toBe('high');
      expect(response.body.status).toBe('todo');
    });

    it('should return 404 for non-existent task', async () => {
      const response = await request(app)
        .get('/api/tasks/99999')
        .set('Authorization', `Bearer ${accessToken}`);

      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Task not found');
    });

    it('should return 403 for task belonging to another user', async () => {
      // Create a second user
      const timestamp = Date.now();
      await request(app)
        .post('/api/auth/register')
        .send({
          username: 'otheruser_' + timestamp,
          email: 'other_' + timestamp + '@example.com',
          password: 'password123'
        });

      const loginResponse = await request(app)
        .post('/api/auth/login')
        .send({
          email: 'other_' + timestamp + '@example.com',
          password: 'password123'
        });

      const otherUserToken = loginResponse.body.accessToken;

      // Create a task for the other user
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${otherUserToken}`)
        .send({
          title: 'Other User Task ' + timestamp,
          description: 'Task belonging to other user',
          priority: 'medium',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Try to access the task with first user's token
      const response = await request(app)
        .get(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`);

      expect(response.status).toBe(403);
      expect(response.body.error).toBe('Access denied');
    });
  });

  describe('PUT /api/tasks/:id', () => {
    it('should update a task', async () => {
      // Create a task
      const timestamp = Date.now();
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Original Title ' + timestamp,
          description: 'Original description',
          priority: 'low',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Update the task
      const response = await request(app)
        .put(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Updated Title ' + timestamp,
          description: 'Updated description',
          priority: 'high',
          status: 'in_progress'
        });

      expect(response.status).toBe(200);
      expect(response.body.title).toBe('Updated Title ' + timestamp);
      expect(response.body.description).toBe('Updated description');
      expect(response.body.priority).toBe('high');
      expect(response.body.status).toBe('in_progress');
    });

    it('should return 400 for invalid update data', async () => {
      // Create a task
      const timestamp = Date.now();
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Valid Task ' + timestamp,
          description: 'Valid description',
          priority: 'medium',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Try to update with invalid priority
      const response = await request(app)
        .put(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          priority: 'invalid_priority'
        });

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    it('should return 404 for non-existent task', async () => {
      const response = await request(app)
        .put('/api/tasks/99999')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Updated Title'
        });

      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Task not found');
    });
  });

  describe('DELETE /api/tasks/:id', () => {
    it('should delete a task', async () => {
      // Create a task
      const timestamp = Date.now();
      const createResponse = await request(app)
        .post('/api/tasks')
        .set('Authorization', `Bearer ${accessToken}`)
        .send({
          title: 'Task to Delete ' + timestamp,
          description: 'This task will be deleted',
          priority: 'medium',
          status: 'todo'
        });

      const taskId = createResponse.body.id;

      // Delete the task
      const response = await request(app)
        .delete(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`);

      expect(response.status).toBe(200);
      expect(response.body.message).toBe('Task deleted successfully');

      // Verify task is deleted
      const getResponse = await request(app)
        .get(`/api/tasks/${taskId}`)
        .set('Authorization', `Bearer ${accessToken}`);

      expect(getResponse.status).toBe(404);
    });

    it('should return 404 for deleting non-existent task', async () => {
      const response = await request(app)
        .delete('/api/tasks/99999')
        .set('Authorization', `Bearer ${accessToken}`);

      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Task not found');
    });
  });
});

