import React, { createContext, useContext, useState, useEffect } from 'react';
import jwt_decode from 'jwt-decode';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem('accessToken');
    const refreshToken = localStorage.getItem('refreshToken');

    if (token) {
      try {
        const decoded = jwt_decode(token);
        // Check if token is expired
        if (decoded.exp * 1000 > Date.now()) {
          setUser({
            id: decoded.userId,
            email: decoded.email,
            username: decoded.username || decoded.email.split('@')[0]
          });
        } else {
          // Token expired, try to refresh
          refreshToken && refreshAccessToken(refreshToken);
        }
      } catch (error) {
        console.error('Invalid token', error);
        logout();
      }
    }
    setLoading(false);
  }, []);

  const refreshAccessToken = async (refreshToken) => {
    try {
      const response = await fetch(`${process.env.VITE_API_URL || 'http://localhost:5000'}/api/auth/refresh-token`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include'
      });

      if (response.ok) {
        const data = await response.json();
        localStorage.setItem('accessToken', data.accessToken);
        const decoded = jwt_decode(data.accessToken);
        setUser({
          id: decoded.userId,
          email: decoded.email,
          username: decoded.username || decoded.email.split('@')[0]
        });
      } else {
        logout();
      }
    } catch (error) {
      console.error('Token refresh failed', error);
      logout();
    }
  };

  const login = async (email, password) => {
    try {
      const response = await fetch(`${process.env.VITE_API_URL || 'http://localhost:5000'}/api/auth/login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        credentials: 'include',
        body: JSON.stringify({ email, password })
      });

      if (response.ok) {
        const data = await response.json();
        localStorage.setItem('accessToken', data.accessToken);
        // Set refresh token as httpOnly cookie (handled by backend)
        const decoded = jwt_decode(data.accessToken);
        setUser({
          id: decoded.userId,
          email: decoded.email,
          username: decoded.username || decoded.email.split('@')[0]
        });
        return { success: true };
      } else {
        const errorData = await response.json();
        return { success: false, error: errorData.error || 'Login failed' };
      }
    } catch (error) {
      console.error('Login error', error);
      return { success: false, error: 'Network error' };
    }
  };

  const register = async (username, email, password) => {
    try {
      const response = await fetch(`${process.env.VITE_API_URL || 'http://localhost:5000'}/api/auth/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ username, email, password })
      });

      if (response.ok) {
        const data = await response.json();
        localStorage.setItem('accessToken', data.accessToken);
        const decoded = jwt_decode(data.accessToken);
        setUser({
          id: decoded.userId,
          email: decoded.email,
          username: decoded.username || decoded.email.split('@')[0]
        });
        return { success: true };
      } else {
        const errorData = await response.json();
        return { success: false, error: errorData.error || 'Registration failed' };
      }
    } catch (error) {
      console.error('Registration error', error);
      return { success: false, error: 'Network error' };
    }
  };

  const logout = () => {
    localStorage.removeItem('accessToken');
    // Clear refresh token cookie (handled by backend)
    setUser(null);
    window.location.href = '/login';
  };

  if (loading) {
    return <div className="flex h-screen items-center justify-center">Loading...</div>;
  }

  return (
    <AuthContext.Provider value={{ user, login, register, logout }}>
      {!user && !loading && window.location.pathname !== '/login' && window.location.pathname !== '/register' ?
        <div className="fixed inset-0 flex items-center justify-center z-50">
          <div className="bg-background/80 backdrop-blur-sm p-6 rounded-lg w-full max-w-md">
            <h2 className="text-2xl font-bold mb-4 text-center">Please log in</h2>
            <p className="text-secondary-text mb-6 text-center">Access your task management dashboard</p>
            <div className="flex justify-center">
              <a href="/login" className="px-6 py-3 bg-accent-color text-white rounded-lg hover:bg-accent-color/90 focus-ring transition-colors">Log In</a>
            </div>
          </div>
        </div>
        :
        children
      }
    </AuthContext.Provider>
  );
};

export const useAuthContext = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuthContext must be used within an AuthProvider');
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';

const TaskContext = createContext();

export const TaskProvider = ({ children }) => {
  const [tasks, setTasks] = useState([]);
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({});
  const [sortOptions, setSortOptions] = useState({ sortBy: 'created_at', sortOrder: 'desc' });
  const [pagination, setPagination] = useState({ limit: 10, offset: 0, total: 0 });

  const fetchTasks = async () => {
    setLoading(true);
    try {
      const queryParams = new URLSearchParams();

      // Add filters
      if (filters.status) queryParams.append('status', filters.status);
      if (filters.priority) queryParams.append('priority', filters.priority);
      if (filters.search) queryParams.append('search', filters.search);
      if (filters.tags && filters.tags.length > 0) {
        queryParams.append('tags', filters.tags.join(','));
      }

      // Add sorting
      if (sortOptions.sortBy) queryParams.append('sortBy', sortOptions.sortBy);
      if (sortOptions.sortOrder) queryParams.append('sortOrder', sortOptions.sortOrder);

      // Add pagination
      if (pagination.limit) queryParams.append('limit', pagination.limit);
      if (pagination.offset) queryParams.append('offset', pagination.offset);

      const response = await fetch(`${process.env.VITE_API_URL || 'http://localhost:5000'}/api/tasks?${queryParams.toString()}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('accessToken')}`
        }
      });

      if (response.ok) {
        const data = await response.json();
        setTasks(data.tasks);
        setPagination(prev => ({ ...prev, total: data.pagination.total }));
      } else {
        console.error('Failed to fetch tasks');
      }
    } catch (error) {
      console.error('Error fetching tasks:', error);
    } finally {
      setLoading(false);
    }
  };

  const addTask = async (taskData) => {
    try {
      const response = await fetch(`${process.env.VITE_API_URL || 'http://localhost:5000'}/api/tasks`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('accessToken')}`
        },
        body: JSON.stringify(taskData)
      });

      if (response.ok) {
        const newTask = await response.json();
        setTasks(prev => [newTask, ...prev]);
        setPagination(prev => ({ ...prev, total: prev.total + 1 }));
        return { success: true, task: newTask };
      } else {
        const errorData = await response.json();
        return { success: false, error: errorData.error || 'Failed to create task' };
      }
    } catch (error) {
      console.error('Error creating task:', error);
      return { success: false, error: 'Network error' };
    }
  };

  const updateTask = async (id, taskData) => {
    try {
      const response = await fetch(`${process.env.VITE_API_URL || 'http://localhost:5000'}/api/tasks/${id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${localStorage.getItem('accessToken')}`
        },
        body: JSON.stringify(taskData)
      });

      if (response.ok) {
        const updatedTask = await response.json();
        setTasks(prev => prev.map(task => task.id === id ? updatedTask : task));
        return { success: true, task: updatedTask };
      } else {
        const errorData = await response.json();
        return { success: false, error: errorData.error || 'Failed to update task' };
      }
    } catch (error) {
      console.error('Error updating task:', error);
      return { success: false, error: 'Network error' };
    }
  };

  const deleteTask = async (id) => {
    try {
      const response = await fetch(`${process.env.VITE_API_URL || 'http://localhost:5000'}/api/tasks/${id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('accessToken')}`
        }
      });

      if (response.ok) {
        setTasks(prev => prev.filter(task => task.id !== id));
        setPagination(prev => ({ ...prev, total: prev.total - 1 }));
        return { success: true };
      } else {
        const errorData = await response.json();
        return { success: false, error: errorData.error || 'Failed to delete task' };
      }
    } catch (error) {
      console.error('Error deleting task:', error);
      return { success: false, error: 'Network error' };
    }
  };

  const toggleTaskStatus = async (id, currentStatus) => {
    const statusMap = {
      todo: 'in_progress',
      in_progress: 'done',
      done: 'todo'
    };

    const newStatus = statusMap[currentStatus] || 'todo';
    return await updateTask(id, { status: newStatus });
  };

  useEffect(() => {
    fetchTasks();
  }, [filters, sortOptions, pagination]);

  if (loading) {
    return <div className="flex h-screen items-center justify-center">Loading tasks...</div>;
  }

  return (
    <TaskContext.Provider value={{ 
      tasks, 
      loading, 
      filters, 
      setFilters,
      sortOptions,
      setSortOptions,
      pagination,
      setPagination,
      fetchTasks,
      addTask,
      updateTask,
      deleteTask,
      toggleTaskStatus
    }}>
      {children}
    </TaskContext.Provider>
  );
};

export const useTaskContext = () => {
  const context = useContext(TaskContext);
  if (!context) {
    throw new Error('useTaskContext must be used within a TaskProvider');
  }
  return context;
};

import React, { useState } from 'react';
