import React from 'react';
import { FiMoreHorizontal, FiCheckCircle, FiMoon, FiSun } from 'react-icons/fi';
import { useTaskContext } from '../../contexts/TaskContext';

const TaskCard = ({ task }) => {
  const { updateTask, deleteTask, toggleTaskStatus } = useTaskContext();

  const priorityColors = {
    high: 'border-danger-color/40',
    medium: 'border-warning-color/40',
    low: 'border-info-color/40'
  };

  const statusVariants = {
    todo: 'border-border-color/20 text-secondary-text',
    in_progress: 'border-warning-color/20 text-warning-color',
    done: 'border-success-color/20 text-success-color'
  };

  const handleStatusClick = async () => {
    await toggleTaskStatus(task.id, task.status);
  };

  const handleDelete = async () => {
    if (window.confirm('Are you sure you want to delete this task?')) {
      await deleteTask(task.id);
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return '';
    const options = { year: 'numeric', month: 'short', day: 'numeric' };
    return new Date(dateString).toLocaleDateString(undefined, options);
  };

  const isOverdue = (dueDate) => {
    if (!dueDate) return false;
    return new Date(dueDate) < new Date() && task.status !== 'done';
  };

  return (
    <div className="bg-surface border-l-4 border-primary-text/10 hover:border-primary-text/20 transition-colors rounded-lg overflow-hidden shadow-sm hover:shadow-md">
      {/* Priority indicator */}
      <div className={`h-4 ${priorityColors[task.priority] || priorityColors.medium}`}></div>

      <div className="p-4">
        <div className="flex justify-between items-start mb-2">
          <div className="flex-1">
            <h3 className="text-lg font-semibold text-primary-text line-clamp-2">
              {task.title}
            </h3>
            {task.description && (
              <p className="mt-1 text-sm text-secondary-text line-clamp-2">
                {task.description}
              </p>
            )}
          </div>

          <div className="ml-3">
            <button 
              onClick={handleStatusClick}
              className={`w-8 h-8 rounded-full flex items-center justify-center ${statusVariants[task.status]} hover:bg-${task.status === 'in_progress' ? 'warning' : task.status === 'done' ? 'success' : 'border'}-color/10 transition-colors focus-ring`}
              aria-label={`Mark as ${task.status === 'todo' ? 'in progress' : task.status === 'in_progress' ? 'done' : 'todo'}`}
            >
              {task.status === 'todo' ? (FiMoon) : task.status === 'in_progress' ? (FiSun) : (FiCheckCircle)}
            </button>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 mb-3 text-xs">
          {task.tags && task.tags.length > 0 && (
            <>
              {task.tags.map((tag, index) => (
                <span key={index} className="px-2 py-0.5 rounded-full bg-border-color/20 text-xs">
                  #{tag}
                </span>
              ))}
            </>
          )}

          <span className="px-2 py-0.5 rounded-full bg-border-color/20 text-xs">
            {formatDate(task.created_at)}
          </span>
        </div>

        {task.due_date && (
          <div className="flex items-center space-x-2 mb-2 text-sm">
            <FiCalendar className="h-4 w-4 text-secondary-text" />
            <span className={`text-${isOverdue(task.due_date) ? 'danger' : 'secondary'}-text font-medium`}>
              {isOverdue(task.due_date) ? 'Overdue' : formatDate(task.due_date)}
            </span>
          </div>
        )}

        <div className="flex justify-end space-x-2">
          <button
            onClick={() => {
              // In a real app, this would open an edit modal
              console.log('Edit task:', task.id);
            }}
            className="text-secondary-text hover:text-primary-text hover:focus-ring p-1 rounded-hover"
          >
            <FiMoreHorizontal className="h-4 w-4" />
          </button>

          <button
            onClick={handleDelete}
            className="text-danger-color hover:text-danger-color/80 hover:focus-ring p-1 rounded-hover"
          >
            <FiTrash2 className="h-4 w-4" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default TaskCard;

