import React, { useState } from 'react';
import { useTaskContext } from '../../contexts/TaskContext';
import TaskCard from '../../ui/TaskCard';
import { FiPlus, FiFilter, FiSearch } from 'react-icons/fi';
import TaskFormModal from './TaskFormModal';
import FilterSidebar from './FilterSidebar';
import EmptyState from './EmptyState';
import SkeletonLoader from '../../ui/SkeletonLoader';

const Dashboard = () => {
  const { tasks, loading, filters, setFilters, sortOptions, setSortOptions, pagination, setPagination, fetchTasks, addTask, updateTask, deleteTask } = useTaskContext();
  const [showAddTaskModal, setShowAddTaskModal] = useState(false);
  const [editTaskId, setEditTaskId] = useState(null);
  const [editTaskData, setEditTaskData] = useState({});
  const [search, setSearch] = useState('');

  const handleAddTask = async (taskData) => {
    const result = await addTask(taskData);
    if (result.success) {
      setShowAddTaskModal(false);
      // Show success toast (would be implemented with a toast library)
      console.log('Task added successfully');
    }
  };

  const handleEditTask = async (taskId, taskData) => {
    const result = await updateTask(taskId, taskData);
    if (result.success) {
      setEditTaskId(null);
      setEditTaskData({});
      console.log('Task updated successfully');
    }
  };

  const handleDeleteTask = async (taskId) => {
    const result = await deleteTask(taskId);
    if (result.success) {
      console.log('Task deleted successfully');
    }
  };

  const handleToggleStatus = async (id, currentStatus) => {
    // This would be handled in the TaskCard component
  };

  const handleSearchChange = (e) => {
    setSearch(e.target.value);
    setFilters(prev => ({ ...prev, search: e.target.value }));
    setPagination(prev => ({ ...prev, offset: 0 })); // Reset to first page
  };

  const handleFilterChange = (newFilters) => {
    setFilters(newFilters);
    setPagination(prev => ({ ...prev, offset: 0 })); // Reset to first page
  };

  const handleSortChange = (sortBy, sortOrder) => {
    setSortOptions({ sortBy, sortOrder });
  };

  const handlePageChange = (offset) => {
    setPagination(prev => ({ ...prev, offset }));
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-4">
        <div className="flex-1 mb-3 md:mb-0">
          <h1 className="text-2xl font-semibold text-primary-text">
            My Tasks
          </h1>
          <p className="text-sm text-secondary-text">
            {tasks.length} tasks
          </p>
        </div>

        <div className="flex items-center space-x-3">
          <input
            type="text"
            placeholder="Search tasks..."
            value={search}
            onChange={handleSearchChange}
            className="w-full max-w-xs px-4 py-2 rounded-lg bg-background/50 border border-border-color text-primary-text placeholder-secondary-text focus:outline-none focus:ring-2 focus:ring-accent-color focus:border-accent-color"
          />

          <button
            onClick={() => setShowAddTaskModal(true)}
            className="relative px-4 py-2 rounded-lg bg-accent-color text-white hover:bg-accent-color/90 focus-ring flex items-center space-x-2 transition-colors"
          >
            <FiPlus className="h-4 w-4" />
            <span>New Task</span>
          </button>
        </div>
      </div>

      {/* Filters and Controls */}
      <div className="flex flex-col md:flex-row md:items-center md:justify-between mb-4">
        <FilterSidebar 
          filters={filters} 
          onFilterChange={handleFilterChange}
          onSortChange={handleSortChange}
        />

        <div className="flex items-center space-x-3 mt-4 md:mt-0">
          <select
            value={pagination.limit}
            onChange={(e) => setPagination(prev => ({ ...prev, limit: parseInt(e.target.value), offset: 0 }))}
            className="px-3 py-1 rounded-lg bg-background/50 border border-border-color text-primary-text focus:outline-none focus:ring-2 focus:ring-accent-color focus:border-accent-color"
          >
            <option value="5">5</option>
            <option value="10">10</option>
            <option value="20">20</option>
            <option value="50">50</option>
          </select>

          <span className="text-sm text-secondary-text">
            Showing {pagination.offset + 1}-{Math.min(pagination.offset + pagination.limit, pagination.total)} of {pagination.total} tasks
          </span>
        </div>
      </div>

      {/* Task List */}
      {loading && tasks.length === 0 ? (
        <div className="space-y-4">
          <SkeletonLoader height={120} width="full" />
          <SkeletonLoader height={120} width="full" />
          <SkeletonLoader height={120} width="full" />
        </div>
      ) : tasks.length > 0 ? (
        <div className="space-y-4">
          {tasks.map((task) => (
            <TaskCard 
              key={task.id} 
              task={task} 
              onEdit={handleEditTask} 
              onDelete={handleDeleteTask}
              onToggleStatus={handleToggleStatus}
            />
          ))}
        </div>
      ) : (
        <EmptyState 
          onAddTask={() => setShowAddTaskModal(true)}
        />
      )}

      {/* Pagination Controls */}
      {pagination.total > pagination.limit && (
        <div className="flex items-center justify-between px-4 py-2 border-t border-border-color">
          <div className="flex-1 space-x-2">
            <button
              onClick={() => handlePageChange(Math.max(0, pagination.offset - pagination.limit))}
              disabled={pagination.offset === 0}
              className="px-3 py-1 rounded-lg bg-background/50 border border-border-color text-primary-text hover:bg-surface/50 focus-ring transition-colors disabled:opacity-50"
            >
              Previous
            </button>

            <button
              onClick={() => handlePageChange(Math.min(pagination.offset + pagination.limit, pagination.total - pagination.limit))}
              disabled={pagination.offset + pagination.limit >= pagination.total}
              className="px-3 py-1 rounded-lg bg-background/50 border border-border-color text-primary-text hover:bg-surface/50 focus-ring transition-colors disabled:opacity-50"
            >
              Next
            </button>
          </div>
          <div className="text-xs text-secondary-text">
            Page {Math.floor(pagination.offset / pagination.limit) + 1} of {Math.ceil(pagination.total / pagination.limit)}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

